  /* the scramble crowd: waits at the four corners, crosses when the pedestrian phase starts */
  const CORN = [[-13.2, -11.6], [13.2, -11.6], [13.2, 11.6], [-13.2, 11.6]], crossers = [];
  for (let i = 0; i < [12, 22, 32][q]; i++) { const c = i % 4, x = CORN[c][0] + (rng() - .5) * 4.4 * Math.sign(CORN[c][0]) * -.2 + (rng() - .5) * 2.6, z = CORN[c][1] + (rng() - .5) * 2.4; const w = crowd.add({ v: V[(i * 3) % V.length], x, z, mode: 'idle', speed: 1.1 + rng() * .5 }); w.corner = c; crossers.push(w) }
