  for (let i = 0; i < [10, 18, 26][q]; i++) { const r = 8.5 + (i % 2) * 1.6, route = []; for (let k = 0; k < 16; k++) { const a = (k / 16 + i / 26) * TAU; route.push([YX + Math.cos(a) * r, YZ + Math.sin(a) * r]) }
    const w = crowd.add({ v: i % 3 ? 'woman' : 'man', x: route[0][0], z: route[0][1], route, loop: true, speed: .55, cols: { skin: [0xf0d0b0, 0xe0b890, 0xc8946a][i % 3], hair: 0x14100c, shirt: YUK[i % 6], pants: YUK[(i + 2) % 6] } }); w.vis = false; dancers.push(w) }
