    yumi: { n: 'Yumi', role: L('DJ at SPACE NEKO', 'DJ en SPACE NEKO'), v: 'woman', cols: { skin: 0xf0d0b0, hair: 0x6a2a8a, shirt: 0x1a1a1a, pants: 0x2a2a3a }, sched: [[12, front('records', 2)], [17, spotIn(IN.kissa, 'cust')], [21, IN.livehouse ? IN.livehouse.F(IN.livehouse.depth - 4.2, 3.4) : null], [3, [-77, 70]]] },
    sora: { n: 'Sora', role: L('rhythm-game champion', 'campeón de juegos de ritmo'), v: 'man', cols: { skin: 0xd8a47a, hair: 0xd8b860, shirt: 0xff4ad2, pants: 0x2a2a6a }, sched: [[11, IN.arcade ? IN.arcade.F(2.4, 3.2) : null], [16, [30, 30]], [19, IN.arcade ? IN.arcade.F(3.4, .6) : null], [1, [-93, -60]]] },
    mei: { n: 'Mei', role: L('shrine maiden (miko)', 'sacerdotisa del santuario (miko)'), v: 'woman', cols: { skin: 0xf0d0b0, hair: 0x14100c, shirt: 0xf4f4f0, pants: 0xc8321e }, sched: [[8, [-94, 142.5]], [17, [-36, 143]], [19, [91.5, 100]], [23, [-70, 150]]] },
